 lai shuo ming zhe ge lei shi xian zhong de yi xie zhu yao fang fa ： Function pop3($server="192.100.100.1",$port=110,$time_out=5) {$this->hostname=$server; $this->port=$port; $this->timeout=$time_out; return true; } shu xi mian xiang dui xiang bian cheng de peng you yi kan jiu hui zhi dao ， zhe shi zhe ge lei de gou zao han shu ， zai chu shi hua zhe ge lei shi ， ke yi gei chu zhe ji ge zui ji ben de shen shu ：pop3 fu wu qi de di zhi ， duan kou hao ， ji lian jie fu wu qi shi de zui da chao shi shi jian 。 yi ban lai shuo ， zhi xu yao gei chu POP3 fu wu qi de di zhi jiu xing le 。 Function open() { if($this->hostname=="") {$this->err_str=" wu xiao de zhu ji ming !!"; return false; } if ($this->debug) echo " zheng zai da kai $this->hostname,$this->port,&$err_no, &$err_str, $this->timeout<BR>"; if (!$this->connection=fsockopen($this->hostname,$this->port,&$err_no, &$err_str, $this->timeout)) { $this->err_str=" lian jie dao POP fu wu qi shi bai ， cuo wu xin xi ：".$err_str." cuo wu hao ：".$err_no; return false; } else { $this->getresp(); if($this->debug)　$this->outdebug($this->resp); if (substr($this->resp,0,3)!="+OK") {$this->err_str=" fu wu qi fan hui wu xiao de xin xi ：".$this->resp." qing jian cha POP fu wu qi shi fou zheng que "; return false; } $this->state="AUTHORIZATION"; return true; } } gai fang fa bu xu yao ren he shen shu jiu ke jian li yu POP3 fu wu qi de sock lian jie 。 gai fang fa you yong dao le ling yi ge lei zhong de fang fa $this->getresp(); xia mian shi zhe ge fang fa de sheng ming ： Function getresp() { for($this->resp="";;) { if(feof($this->connection)) return false; $this->resp.=fgets($this->connection,100); $length=strlen($this->resp); if($length>=2 && substr($this->resp,$length-2,2)=="\r\n") { $this->resp=strtok($this->resp,"\r\n"); return true; } } } zhe ge fang fa qu de fu wu qi duan de fan hui xin xi bing jin xing jian dan de chu li ： qu diao zui hou de hui che huan xing fu ， jiang fan hui xin xi bao cun zai resp zhe ge nei bu bian liang zhong 。 