ue zhi xing le 。 ye ke yi yong qian mian ti dao guo de san ge zi fu "+OK" zuo wei pan duan de biao shi 。 xia mian jie shao de ji ge fang fa ze ke yi an zhao qian shu shou qu xin jian de dui hua qu li jie ， yin wei you guan de nei rong yi jing zai qian mian zuo le shuo ming ， yin ci xia mian de fang fa bu zuo xiang xi de shuo ming ， qing shen kao qi zhong de zhu shi ： Function Login($user,$password)　// fa song yong hu ming ji mi ma ， deng lu dao fu wu qi { if($this->state!="AUTHORIZATION") { $this->err_str=" huan mei you lian jie dao fu wu qi huo zhuang tai bu dui "; return false; } if (!$this->apop) // fu wu qi shi fou cai yong APOP yong hu ren zheng { if (!$this->command("USER $user",3,"+OK")) return false; if (!$this->command("PASS $password",3,"+OK")) return false; } else { //echo $this->resp=strtok($this->resp,"\r\n"); if (!$this->command("APOP $user ".md5($this->greeting.$password),3,"+OK")) return false; } $this->state="TRANSACTION"; // yong hu ren zheng tong guo ， jin ru chuan song mo shi return true; } Function stat() // dui ying zhe stat ming ling ， qu de zong de you jian shu yu zong de da xiao { if($this->state!="TRANSACTION") { $this->err_str=" huan mei you lian jie dao fu wu qi huo mei you cheng gong deng lu "; return false; } if (!$this->command("STAT",3,"+OK")) return false; else { $this->resp=strtok($this->resp," "); $this->messages=strtok(" "); // qu de you jian zong shu $this->size=strtok(" "); // qu de zong de zi jie da xiao return true; } } Function listmail($mess=null,$uni_id=null) // dui ying de shi LIST ming ling ， qu de mei ge you jian de da xiao ji xu hao 。 yi ban lai shuo yong dao de shi List ming ling ， ru guo zhi ding le $uni_id ， ze shi yong UIDL ming ling ， fan hui de shi mei ge you jian de biao shi fu ， shi shi shang ， zhe ge biao shi fu yi ban shi mei you shen me yong de 。 qu de de ge ge you jian de da xiao fan hui dao lei de nei bu bian liang mail_list zhe ge er wei shu zu li 。 { if($this->state!="TRANSACTION") { $this->err_str=" huan mei you lian jie dao fu wu qi huo mei you cheng gong deng lu "; return false; } if ($uni_id) $command="UIDL "; else $command="LIST "; if ($mess) $command.=$mess; if (!$this->command($command,3,"+OK")) { //echo $this->err_str; return false; } else { $i=0; $this->mail_list=array(); $this->getresp(); while ($this->resp!=".") { $i++; if ($this->debug) { $this->outdebug($this->resp); } if ($uni_id) { $this->mail_list[$i][num]=strtok($this->resp," "); $this->mail_list[$i][size]=strtok(" "); } else { $this->mail_list[$i]["num"]=intval(strtok($this->resp," ")); $this->mail_list[$i]["size"]=intval(strtok(" ")); } $this->getresp(); } return true; } } function getmail($num=1,$line=-1)　// qu de you jian de nei rong ，$num shi you jian de xu hao ，$line shi zhi ding gong qu de zheng wen de duo shao xing 。 you xie shi hou ， ru you jian bi jiao da er wo men zhi xiang xian cha kan you jian de zhu ti shi shi bi xu zhi ding xing shu de 。 mo ren zhi $line=-1， ji qu hui suo you de you jian nei rong ， qu de de nei rong cun fang dao nei bu bian liang $head，$body liang ge shu zu li ， shu zu li de mei yi ge yuan su dui ying de shi you jian yuan dai ma de yi xing 。 { if($this->state!="TRANSACTION") { $this->err_str=" bu neng shou qu xin jian ， huan mei you lian jie dao fu wu qi huo mei you cheng gong deng lu "; return false; } if ($line<0) $command="RETR $num"; else $command="TOP $num $line"; if (!$this->command("$command",3,"+OK")) return false; else { $this->getresp(); $is_head=true; while ($this->resp!=".") // . hao shi you jian jie shu de biao shi { if ($this->debug) $this->outdebug($this->resp); if (substr($this->resp,0,1)==".") $this->resp=substr($this->resp,1,strlen($this->resp)-1); if (trim($this->resp)=="") // you jian tou yu zheng wen bu fen de shi yi ge kong xing $is_head=false; if ($is_head) $this->head[]=$this->resp; else $this->body[]=$this->resp; $this->getresp(); } return true; } } // end function function dele($num) // shan chu zhi ding xu hao de you jian ，$num shi fu wu qi shang de you jian xu hao { if($this->state!="TRANSACTION") { $this->err_str=" bu neng shan chu yuan cheng xin jian ， huan mei you lian jie dao fu wu qi huo mei you cheng gong deng lu "; return false; } if (!$num) { $this->err_str=" shan chu de shen shu bu dui "; return false; } if ($this->command("DELE $num ",3,"+OK")) return true; else return false; } tong guo yi shang ji ge fang fa ， wo men yi jing ke yi shi xian you jian de cha kan 、 shou qu 、 shan chu de cao zuo ， bu guo bie wang le zui hou yao tui chu ， bing guan bi yu fu wu qi de lian jie ， tiao yong xia mian de zhe ge fang fa ： Function Close() { if($this->connection!=0) { if($this->state=="TRANSACTION") $this->command("QUIT",3,"+OK"); fclose($this->connection); $this->connection=0; $this->state="DISCONNECTED"; } }

